def masked_loss(token_losses, mask):
    if sum(mask) == 0:
        raise ValueError("mask selects no tokens")
    total = sum(l * m for l, m in zip(token_losses, mask))
    return total / sum(mask)

def assistant_mask(tokens):
    mask = []
    inside = False
    for t in tokens:
        if t == '<assistant>':
            mask.append(0)
            inside = True
        elif t == '<end>':
            mask.append(1 if inside else 0)
            inside = False
        else:
            mask.append(1 if inside else 0)
    return mask

import numpy as np

def lora_forward(W, A, B, x, alpha):
    r = A.shape[0]
    return W @ x + (alpha / r) * (B @ (A @ x))

def lora_params(d_out, d_in, r):
    return r * d_in + d_out * r
